{"function":"() => {
const lum=c=>{const m=c.match(/[\d.]+/g).map(Number);const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)};return 0.2126*f(m[0])+0.7152*f(m[1])+0.0722*f(m[2])};
const cr=(a,b)=>{const x=lum(a),y=lum(b);return ((Math.max(x,y)+0.05)/(Math.min(x,y)+0.05)).toFixed(2)};
const out={};
for(const id of ['cpf','servico','data-preferencial']){const e=document.getElementById(id);const p=getComputedStyle(e,'::placeholder');out['ph-'+id]=[p.color,p.opacity,getComputedStyle(e).backgroundColor,cr(p.color,getComputedStyle(e).backgroundColor)]}
const bc=document.querySelector('.crumb a:not(.br-button)');const s=getComputedStyle(bc);out.crumb=[s.color,cr(s.color,'rgb(248,248,248)'),s.fontSize,getComputedStyle(document.body).backgroundColor];
const up=document.querySelector('.upload-button');out.upload=[getComputedStyle(up).borderColor,getComputedStyle(up).borderStyle,getComputedStyle(up).borderWidth];
const ch=document.querySelector('.br-checkbox label');out.cbbefore=getComputedStyle(ch,'::before').borderColor;
const rd=document.querySelector('.br-radio label[for=forma-video]');out.rdbefore=[getComputedStyle(rd,'::before').borderColor,getComputedStyle(rd,'::before').borderWidth];
const th=document.querySelector('.titulo-historico');out.h=[th.tagName];
out.headings=[...document.querySelectorAll('h1,h2,h3,h4')].map(h=>h.tagName+h.textContent);
out.landmarks=[...document.querySelectorAll('header,nav,main,footer,[role=banner]')].map(e=>e.tagName);
return out}"}

